import{_ as o,a0 as t,w as r,s as d,ao as l,I as a,x as n,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 上使用 groff -me 格式化你的學術論文 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 groff -me 格式化你的學術論文 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 groff -me 格式化你的學術論文 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 groff -me 格式化你的學術論文 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180220 How to format academic papers on Linux with groff -me","title":"在 Linux 上使用 groff -me 格式化你的學術論文","tag":"201805","desc":""},"relativePath":"201805/20180220 How to format academic papers on Linux with groff -me.md","filePath":"[post].md"}'),c={name:"201805/20180220 How to format academic papers on Linux with groff -me.md"};function f(u,s,h,g,m,b){const e=t("Link");return r(),d("div",null,[s[35]||(s[35]=l('<h1 id="在-linux-上使用-groff-me-格式化你的學術論文" tabindex="-1">在 Linux 上使用 groff -me 格式化你的學術論文 <a class="header-anchor" href="#在-linux-上使用-groff-me-格式化你的學術論文" aria-label="Permalink to “在 Linux 上使用 groff -me 格式化你的學術論文”">​</a></h1><blockquote><p>學習用簡單的宏為你的課程論文添加腳註、引用、子標題及其它格式。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life_paperclips.png?itok=j48op49T" alt=""></p><p>當我在 1993 年發現 Linux 時，我還是一名本科生。我很興奮在我的宿舍裏擁有 Unix 系統的強大功能，但是儘管它有很多功能，但 Linux 卻缺乏應用程序。像 LibreOffice 和 OpenOffice 這樣的文字處理程序還需要幾年的時間才出現。如果你想使用文字處理器，你可能會將你的系統引導到 MS-DOS 中，並使用 WordPerfect、共享軟件 GalaxyWrite 或類似的程序。</p><p>這就是我的方法，因為我需要為我的課程寫論文，但我更喜歡呆在 Linux 中。我從我們的 “大 Unix” 校園計算機實驗室得知，Unix 系統提供了一組文本格式化的程序 <code>nroff</code> 和 <code>troff </code> ，它們是同一系統的不同接口：<code>nroff</code> 生成純文本輸出，適用於屏幕或行式打印機，而 <code>troff</code> 產生非常優美的輸出，通常用於在激光打印機上打印。</p>',5)),a("p",null,[s[1]||(s[1]=n("在 Linux 上，",-1)),s[2]||(s[2]=a("code",null,"nroff",-1)),s[3]||(s[3]=n(" 和 ",-1)),s[4]||(s[4]=a("code",null,"troff",-1)),s[5]||(s[5]=n(" 被合併為 GNU troff，通常被稱為 ",-1)),p(e,{href:"https://www.gnu.org/software/groff/"},{default:i(()=>[...s[0]||(s[0]=[n("groff",-1)])]),_:1}),s[6]||(s[6]=n("。 我很高興看到早期的 Linux 發行版中包含了某個版本的 groff，因此我着手學習如何使用它來編寫課程論文。 我學到的第一個宏集是 ",-1)),s[7]||(s[7]=a("code",null,"-me",-1)),s[8]||(s[8]=n(" 宏包，一個簡單易學的宏集。",-1))]),s[36]||(s[36]=l(`<p>關於 <code>groff</code> ，首先要了解的是它根據一組宏來處理和格式化文本。宏通常是個兩個字符的命令，它自己設置在一行上，並帶有一個引導點。宏可能包含一個或多個選項。當 <code>groff</code> 在處理文檔時遇到這些宏中的一個時，它會自動對文本進行格式化。</p><p>下面，我將分享使用 <code>groff -me</code> 編寫課程論文等簡單文檔的基礎知識。 我不會深入細節進行討論，比如如何創建嵌套列表，保存和顯示，以及使用表格和數字。</p><h3 id="段落" tabindex="-1">段落 <a class="header-anchor" href="#段落" aria-label="Permalink to “段落”">​</a></h3><p>讓我們從一個簡單的例子開始，在幾乎所有類型的文檔中都可以看到：段落。段落可以格式化為首行縮進或不縮進（即，與左邊齊平）。 包括學術論文，雜誌，期刊和書籍在內的許多印刷文檔都使用了這兩種類型的組合，其中文檔或章節中的第一個（主要）段落左側對齊，而所有其他（常規）的段落縮進。 在 <code>groff -me</code>中，您可以使用兩種段落類型：前導段落（<code>.lp</code>）和常規段落（<code>.pp</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.lp</span></span>
<span class="line"><span>This is the first paragraph.</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>This is a standard paragraph.</span></span></code></pre></div><h3 id="文本格式" tabindex="-1">文本格式 <a class="header-anchor" href="#文本格式" aria-label="Permalink to “文本格式”">​</a></h3><p>用粗體格式化文本的宏是 <code>.b</code>，斜體格式是 <code>.i</code> 。 如果您將 <code>.b</code> 或 <code>.i</code> 放在一行上，則後面的所有文本將以粗體或斜體顯示。 但更有可能你只是想用粗體或斜體來表示一個或幾個詞。 要將一個詞加粗或斜體，將該單詞放在與 <code>.b</code> 或 <code>.i</code> 相同的行上作為選項。 要用粗體或斜體格式化多個單詞，請將文字用引號引起來。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>You can do basic formatting such as</span></span>
<span class="line"><span>.i italics</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>.b &quot;bold text.&quot;</span></span></code></pre></div><p>在上面的例子中，粗體文本結尾的句點也是粗體。 在大多數情況下，這不是你想要的。 只要文字是粗體字，而不是後面的句點也是粗體字。 要獲得您想要的效果，您可以向 <code>.b</code> 或 <code>.i</code> 添加第二個參數，以指示以粗體或斜體顯示的文本後面跟着的任意文本以正常類型顯示。 您可以這樣做，以確保尾隨句點不會以粗體顯示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>You can do basic formatting such as</span></span>
<span class="line"><span>.i italics</span></span>
<span class="line"><span>or</span></span>
<span class="line"><span>.b &quot;bold text&quot; .</span></span></code></pre></div><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to “列表”">​</a></h3><p>使用 <code>groff -me</code>，您可以創建兩種類型的列表：無序列表（<code>.bu</code>）和有序列表（<code>.np</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Bullet lists are easy to make:</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Apple</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Banana</span></span>
<span class="line"><span>.bu</span></span>
<span class="line"><span>Pineapple</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Numbered lists are as easy as:</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>One</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>Two</span></span>
<span class="line"><span>.np</span></span>
<span class="line"><span>Three</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Note that numbered lists will reset at the next pp or lp.</span></span></code></pre></div><h3 id="副標題" tabindex="-1">副標題 <a class="header-anchor" href="#副標題" aria-label="Permalink to “副標題”">​</a></h3><p>如果你正在寫一篇長論文，你可能想把你的內容分成幾部分。使用 <code>groff -me</code>，您可以創建編號的標題（<code>.sh</code>） 和未編號的標題 （<code>.uh</code>）。在這兩種方法中，將節標題作為參數括起來。對於編號的標題，您還需要提供標題級別 <code>:1</code> 將給出一個一級標題(例如，<code>1</code>)。同樣，<code>2</code> 和 <code>3</code> 將給出第二和第三級標題，如 <code>2.1</code> 或 <code>3.1.1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.uh Introduction</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Provide one or two paragraphs to describe the work</span></span>
<span class="line"><span>and why it is important.</span></span>
<span class="line"><span>.sh 1 &quot;Method and Tools&quot;</span></span>
<span class="line"><span>.pp</span></span>
<span class="line"><span>Provide a few paragraphs to describe how you</span></span>
<span class="line"><span>did the research, including what equipment you used</span></span></code></pre></div><h3 id="智能引號和塊引號" tabindex="-1">智能引號和塊引號 <a class="header-anchor" href="#智能引號和塊引號" aria-label="Permalink to “智能引號和塊引號”">​</a></h3><p>在任何學術論文中，引用他人的工作作為證據都是正常的。如果你引用一個簡短的引用來突出一個關鍵信息，你可以在你的文本週圍鍵入引號。但是 groff 不會自動將你的引用轉換成現代文字處理系統所使用的“智能”或“捲曲”引用。要在 <code>groff -me</code> 中創建它們，插入一個內聯宏來創建左引號（<code>\\*(lq</code>）和右引號（<code>\\*(rq</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson coined the phrase \\*(lqopen source.\\*(rq</span></span></code></pre></div><p><code>groff -me</code> 中還有一個快捷方式來創建這些引號（<code>.q</code>），我發現它更易於使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson coined the phrase</span></span>
<span class="line"><span>.q &quot;open source.&quot;</span></span></code></pre></div><p>如果引用的是跨越幾行的較長的引用，則需要使用一個塊引用。為此，在引用的開頭和結尾插入塊引用宏（<code>.(q</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson recently wrote about open source:</span></span>
<span class="line"><span>.(q</span></span>
<span class="line"><span>On April 7, 1998, Tim O&#39;Reilly held a meeting of key</span></span>
<span class="line"><span>leaders in the field. Announced in advance as the first</span></span>
<span class="line"><span>.q &quot;Freeware Summit,&quot;</span></span>
<span class="line"><span>by April 14 it was referred to as the first</span></span>
<span class="line"><span>.q &quot;Open Source Summit.&quot;</span></span>
<span class="line"><span>.)q</span></span></code></pre></div><h3 id="腳註" tabindex="-1">腳註 <a class="header-anchor" href="#腳註" aria-label="Permalink to “腳註”">​</a></h3><p>要插入腳註，請在腳註文本前後添加腳註宏（<code>.(f</code>），並使用內聯宏（<code>\\**</code>）添加腳註標記。腳註標記應出現在文本中和腳註中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.pp</span></span>
<span class="line"><span>Christine Peterson recently wrote about open source:\\**</span></span>
<span class="line"><span>.(f</span></span>
<span class="line"><span>\\**Christine Peterson.</span></span>
<span class="line"><span>.q &quot;How I coined the term open source.&quot;</span></span>
<span class="line"><span>.i &quot;OpenSource.com.&quot;</span></span>
<span class="line"><span>1 Feb 2018.</span></span>
<span class="line"><span>.)f</span></span>
<span class="line"><span>.(q</span></span>
<span class="line"><span>On April 7, 1998, Tim O&#39;Reilly held a meeting of key</span></span>
<span class="line"><span>leaders in the field. Announced in advance as the first</span></span>
<span class="line"><span>.q &quot;Freeware Summit,&quot;</span></span>
<span class="line"><span>by April 14 it was referred to as the first</span></span>
<span class="line"><span>.q &quot;Open Source Summit.&quot;</span></span>
<span class="line"><span>.)q</span></span></code></pre></div><h3 id="封面" tabindex="-1">封面 <a class="header-anchor" href="#封面" aria-label="Permalink to “封面”">​</a></h3><p>大多數課程論文都需要一個包含論文標題，姓名和日期的封面。 在 <code>groff -me</code> 中創建封面需要一些組件。 我發現最簡單的方法是使用居中的文本塊並在標題、名字和日期之間添加額外的行。 （我傾向於在每一行之間使用兩個空行）。在文章頂部，從標題頁（<code>.tp</code>）宏開始，插入五個空白行（<code>.sp 5</code>），然後添加居中文本（<code>.(c</code>） 和額外的空白行（<code>.sp 2</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>.tp</span></span>
<span class="line"><span>.sp 5</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>.b &quot;Writing Class Papers with groff -me&quot;</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.sp 2</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>Jim Hall</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.sp 2</span></span>
<span class="line"><span>.(c</span></span>
<span class="line"><span>February XX, 2018</span></span>
<span class="line"><span>.)c</span></span>
<span class="line"><span>.bp</span></span></code></pre></div><p>最後一個宏（<code>.bp</code>）告訴 groff 在標題頁後添加一個分頁符。</p><h3 id="更多內容" tabindex="-1">更多內容 <a class="header-anchor" href="#更多內容" aria-label="Permalink to “更多內容”">​</a></h3><p>這些是用 <code>groff-me</code> 寫一份專業的論文非常基礎的東西，包括前導和縮進段落，粗體和斜體，有序和無需列表，編號和不編號的章節標題，塊引用以及腳註。</p>`,32)),a("p",null,[s[11]||(s[11]=n("我已經包含一個",-1)),p(e,{href:"https://opensource.com/sites/default/files/lorem-ipsum.me_.txt"},{default:i(()=>[...s[9]||(s[9]=[n("示例 groff 文件",-1)])]),_:1}),s[12]||(s[12]=n("來演示所有這些格式。 將 ",-1)),s[13]||(s[13]=a("code",null,"lorem-ipsum.me",-1)),s[14]||(s[14]=n(" 文件保存到您的系統並通過 groff 運行。 ",-1)),s[15]||(s[15]=a("code",null,"-Tps",-1)),s[16]||(s[16]=n(" 選項將輸出類型設置為 ",-1)),s[17]||(s[17]=a("code",null,"PostScript",-1)),s[18]||(s[18]=n(" ，以便您可以將文檔發送到打印機或使用 ",-1)),s[19]||(s[19]=a("code",null,"ps2pdf",-1)),s[20]||(s[20]=n(" 程序將其轉換為 ",-1)),p(e,{href:"https://opensource.com/sites/default/files/lorem-ipsum.me_.pdf"},{default:i(()=>[...s[10]||(s[10]=[n("PDF 文件",-1)])]),_:1}),s[21]||(s[21]=n("。",-1))]),s[37]||(s[37]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>groff -Tps -me lorem-ipsum.me &gt; lorem-ipsum.me.ps</span></span>
<span class="line"><span>ps2pdf lorem-ipsum.me.ps lorem-ipsum.me.pdf</span></span></code></pre></div><p>如果你想使用 <code>groff -me</code> 的更多高級功能，請參閲 Eric Allman 所著的 “使用 Groff -me 來寫論文”，你可以在你係統的 groff 的 <code>doc</code> 目錄下找到一個名叫 <code>meintro.me</code> 的文件。這份文檔非常完美的説明了如何使用 <code>groff-me</code> 宏來格式化你的論文。</p><hr>`,3)),a("p",null,[s[23]||(s[23]=n("via: ",-1)),p(e,{href:"https://opensource.com/article/18/2/how-format-academic-papers-linux-groff-me"},{default:i(()=>[...s[22]||(s[22]=[n("https://opensource.com/article/18/2/how-format-academic-papers-linux-groff-me",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("作者：",-1)),p(e,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[24]||(s[24]=[n("Jim Hall",-1)])]),_:1}),s[28]||(s[28]=n(" 譯者：",-1)),p(e,{href:"https://github.com/amwps290"},{default:i(()=>[...s[25]||(s[25]=[n("amwps290",-1)])]),_:1}),s[29]||(s[29]=n(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[26]||(s[26]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[32]||(s[32]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[30]||(s[30]=[n("LCTT",-1)])]),_:1}),s[33]||(s[33]=n(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[31]||(s[31]=[n("Linux中國",-1)])]),_:1}),s[34]||(s[34]=n(" 榮譽推出",-1))])])}const C=o(c,[["render",f]]);export{y as __pageData,C as default};
